+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_FILE = path.join(process.cwd(), ".cache", "sessions.json");
+let store = new Map<string, Entry>();
+
+const ensureCacheDir = () => {
+  const dir = path.dirname(CACHE_FILE);
+  if (!fs.existsSync(dir)) {
+    fs.mkdirSync(dir, { recursive: true });
+  }
+};
+
+const loadCache = () => {
+  ensureCacheDir();
+  if (fs.existsSync(CACHE_FILE)) {
+    try {
+      const data = fs.readFileSync(CACHE_FILE, "utf-8");
+      const entries = JSON.parse(data);
+      store = new Map(entries);
+    } catch {
+      store = new Map();
+    }
+  }
+};
+
+const persistCache = () => {
+  ensureCacheDir();
+  const entries = Array.from(store.entries());
+  fs.writeFileSync(CACHE_FILE, JSON.stringify(entries), "utf-8");
+};
+
+loadCache();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  persistCache();
 };

